  ($x$Cholesterol bidirectional fluidity buffering$x$, $x$CHOLESTEROL_STRUCTURE_MEMBRANE_ROLE$x$),
  ($x$Isoprene unit counting in terpenes$x$, $x$TERPENES_ISOPRENE_UNITS$x$),
  ($x$Squalene as hexaisoprenoid steroid precursor$x$, $x$TERPENES_ISOPRENE_UNITS$x$),
  ($x$Terpene unit counting convention$x$, $x$TERPENES_ISOPRENE_UNITS$x$),
  ($x$Terpene versus steroid structural discrimination$x$, $x$TERPENES_ISOPRENE_UNITS$x$),
  ($x$Retinal aldehyde as visual chromophore$x$, $x$FAT_SOLUBLE_VITAMINS_CAROTENOIDS$x$),
  ($x$Retinoic acid supports epithelial development$x$, $x$FAT_SOLUBLE_VITAMINS_CAROTENOIDS$x$),
  ($x$Conjugation length sets carotene color$x$, $x$FAT_SOLUBLE_VITAMINS_CAROTENOIDS$x$),
  ($x$Tocopherol chain-breaking site in membranes$x$, $x$FAT_SOLUBLE_VITAMINS_CAROTENOIDS$x$),
  ($x$Vitamin K glutamate carboxylation chemistry$x$, $x$FAT_SOLUBLE_VITAMINS_CAROTENOIDS$x$),
  ($x$Prostaglandin autocrine paracrine locality$x$, $x$EICOSANOID_SIGNALLING$x$),
  ($x$Enzyme blockade reveals mediator function$x$, $x$EICOSANOID_SIGNALLING$x$),
  ($x$Steroid nucleus recognition in novel isolates$x$, $x$STEROID_STRUCTURE_DERIVATIVES$x$),
  ($x$Vitamin D3 as a ring-opened steroid derivative$x$, $x$STEROID_STRUCTURE_DERIVATIVES$x$),
  ($x$Trans double bond chain packing$x$, $x$FATTY_ACID_SATURATION_PACKING$x$),
  ($x$Triacylglycerol backbone structure$x$, $x$TRIACYLGLYCEROL_STRUCTURE_HYDROLYSIS$x$),
  ($x$Triacylglycerol complete hydrolysis stoichiometry$x$, $x$TRIACYLGLYCEROL_STRUCTURE_HYDROLYSIS$x$),
  ($x$Wax barrier against water loss$x$, $x$WAXES$x$),
  ($x$Wax ester structure and inertness$x$, $x$WAXES$x$),
  ($x$Wax versus triacylglycerol backbone identity$x$, $x$WAXES$x$),
  ($x$Wax classification from hydrolysis products$x$, $x$WAXES$x$),
  ($x$Storage capacity from bile concentration$x$, $x$LIPID_DIGESTION_BILE$x$),
  ($x$Pump failure versus open outlet in bile delivery$x$, $x$LIPID_DIGESTION_BILE$x$),
  ($x$Positive control in a bile diversion study$x$, $x$LIPID_DIGESTION_BILE$x$),
  ($x$multi-ion permeability equation selection$x$, $x$RESTING_MEMBRANE_POTENTIAL$x$),
  ($x$vesicle anion equilibrium potential sign$x$, $x$ION_CHANNELS$x$)
) AS m(descriptor, slug) ON m.descriptor = q.subtopic
JOIN public.concepts c ON c.slug = m.slug
WHERE c.status <> 'DEPRECATED'
ON CONFLICT (question_id, concept_id) DO NOTHING;
-- ────────────────────────────────────────────────────────────
-- Verification
-- ────────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.concepts)                       AS concepts,          -- 576
  (SELECT count(*) FROM public.question_concepts)              AS mappings,          -- 2659
  (SELECT count(*) FROM public.flashcard_concepts)             AS flashcard_maps,    -- 0
  (SELECT count(*) FROM public.concept_aliases)                AS aliases,           -- 1
  (SELECT count(*) FROM public.questions)                      AS questions,         -- 2681
  (SELECT count(*) FROM public.flashcards)                     AS flashcards,        -- 4117
  (SELECT count(*) FROM public.question_distractor_metadata)   AS distractors;       -- 8043

-- The rename kept the ID and filed the old name. Expect one row, LEGACY_NAME.
SELECT c.slug, c.canonical_name, a.alias, a.alias_type
FROM public.concepts c JOIN public.concept_aliases a ON a.concept_id = c.id
WHERE c.canonical_name = 'Respiratory Thermoregulation';

-- Coverage. Expect 2659 mapped, 22 unmapped.
SELECT count(*) FILTER (WHERE qc.question_id IS NOT NULL) AS mapped,
       count(*) FILTER (WHERE qc.question_id IS NULL)     AS unmapped
FROM public.questions q
LEFT JOIN public.question_concepts qc ON qc.question_id = q.id;

-- Section compatibility by membership. Expect zero rows.
SELECT 'section mismatch' AS problem, count(*) AS n
FROM public.question_concepts qc
JOIN public.questions q ON q.id = qc.question_id
JOIN public.legacy_taxonomy_map m
  ON m.source_system='questions' AND m.source_field='section' AND m.source_value=q.section
WHERE NOT EXISTS (SELECT 1 FROM public.concept_sections cs
                  WHERE cs.concept_id=qc.concept_id AND cs.section_code=m.section_code);

-- Exactly one PRIMARY per question. Expect zero rows.
SELECT 'duplicate primary' AS problem, question_id, count(*)
FROM public.question_concepts WHERE role='PRIMARY'
GROUP BY question_id HAVING count(*) > 1;

-- Largest concepts, watching for a catch-all.
SELECT c.canonical_name, count(*) AS questions
FROM public.question_concepts qc JOIN public.concepts c ON c.id=qc.concept_id
GROUP BY c.canonical_name ORDER BY count(*) DESC LIMIT 6;

